import {ReleasesDomainAdapter,                     } from '../../../adapters/releases/domain-adapter.js';
import {ConfigurationDomainAdapter} from '../../../adapters/configuration/domain-adapter.js';
import {createReleasesSurfaceComposition} from '../../../surfaces/releases/composition.js';
import {createConfigurationSurfaceComposition} from '../../../surfaces/configuration/composition.js';

const assert=(value    ,message='assertion failed')=>{if(!value)throw Error(message)};
const run=(name       ,fn         ,out      )=>{try{fn();out.push({name,status:'PASS'})}catch(error){out.push({name,status:'FAIL',error:String((error       )?.message||error)})}};
const h=(c       )=>c.repeat(64);
const candidate=(id       ,patch    ={})                 =>({candidateId:id,commitSHA:h(id==='A'?'a':'e'),treeSHA:h(id==='A'?'b':'f'),artifactDigest:h(id==='A'?'c':'1'),state:'TECHNICALLY_READY',evidenceDigest:h(id==='A'?'d':'2'),authorization:'NONE',deployment:'NOT_DEPLOYED',deploymentObservedAt:null,...patch});
const obs=(patch    ={})=>({key:'runtime.maxItems',presentVersion:'v7',redactedValue:'***12',source:'local-runtime-safe-config',observedAt:'2026-09-18T00:00:00Z',restartRequired:false,state:'AVAILABLE',...patch});

export function runS19Tests(){const tests      =[];
  run('S19.releases.exact-pair-is-pinned-through-AnalyticalCompareOwner',()=>{const a=new ReleasesDomainAdapter({candidates:[candidate('A'),candidate('B')]});const c=createReleasesSurfaceComposition({adapter:a});const blocked=c.commands.execute('releases.compare',{});assert(blocked.ok===false);const r=c.commands.execute('releases.compare',{leftId:'A',rightId:'B'});assert(r.ok&&r.mode==='EXACT_PAIR'&&r.pinned===true&&r.mutable===false&&r.leftRef.candidateId==='A'&&r.rightRef.candidateId==='B'&&r.receipt.owner==='AnalyticalCompareOwner')},tests);
  run('S19.releases.latest-alias-cannot-replace-exact-pair',()=>{const a=new ReleasesDomainAdapter({candidates:[candidate('A'),candidate('B')]});const first=a.compare({leftId:'A',rightId:'B'}),head=a.compare({id:'A',currentHeadCommitSHA:h('9')});assert(first.leftRef.commitSHA===h('a')&&first.rightRef.commitSHA===h('e')&&head.stale===true&&head.doesNotReplaceExactPairCompare===true)},tests);
  run('S19.releases.evidence-binding-mismatch-rejected',()=>{let failed=false;try{new ReleasesDomainAdapter({candidates:[candidate('A',{evidenceBinding:{digest:h('d'),candidateRef:{candidateId:'B',commitSHA:h('e'),treeSHA:h('f'),artifactDigest:h('1')},method:'TEST'},})]})}catch(error){failed=String((error       ).message).includes('RELEASE_EVIDENCE_CANDIDATE_BINDING_MISMATCH')}assert(failed)},tests);
  run('S19.releases.readiness-is-not-authorization-or-deployment',()=>{const a=new ReleasesDomainAdapter({candidates:[candidate('A')]});const r=a.inspect('A');assert(r.ok&&r.candidate.state==='TECHNICALLY_READY'&&r.candidate.authorization==='NONE'&&r.candidate.deployment==='NOT_DEPLOYED'&&r.truth.technicalReadinessIsAuthorization===false&&r.truth.authorizationIsDeployment===false)},tests);
  run('S19.releases.authorization-request-never-deploys',()=>{const a=new ReleasesDomainAdapter({candidates:[candidate('A')],requester:{request:()=>({requestId:'owner-request-1',state:'REQUESTED'})}});a.select('A');const r=a.requestAuthorization();assert(r.ok&&r.authorization==='REQUESTED'&&r.deployment==='NOT_DEPLOYED'&&r.executesAuthorizationDecision===false&&r.executesDeployment===false)},tests);
  run('S19.releases.plan-is-nonexecuting-and-candidate-bound',()=>{const a=new ReleasesDomainAdapter({candidates:[candidate('A')]});const r=a.plan('A');assert(r.ok&&r.candidateRef.commitSHA===h('a')&&r.technicalEvidence?.candidateRef.candidateId==='A'&&r.executesAuthorization===false&&r.executesDeployment===false)},tests);
  run('S19.releases.composition-keeps-four-truth-axes-separate',()=>{const c=createReleasesSurfaceComposition({adapter:new ReleasesDomainAdapter({candidates:[candidate('A'),candidate('B')]})});assert(c.slots.CENTER==='ReleaseGovernanceWorkbench'&&c.compareBinding.owner==='AnalyticalCompareOwner'&&c.truthCeiling.technicalReadinessIsOwnerAuthorization===false&&c.truthCeiling.ownerAuthorizationIsDeployment===false)},tests);

  run('S19.configuration.edit-is-proposal-only',()=>{let calls=0;const a=new ConfigurationDomainAdapter({observations:[obs()],authority:{id:'cfg-authority',requestApply:()=>{calls++;return {status:'APPLY_REQUESTED',authorityId:'cfg-authority'}}}});a.beginProposal('runtime.maxItems','14');assert(calls===0&&a.proposal('runtime.maxItems')?.application==='NOT_APPLIED')},tests);
  run('S19.configuration.validate-never-applies',()=>{let calls=0;const a=new ConfigurationDomainAdapter({observations:[obs()],authority:{id:'cfg-authority',requestApply:()=>{calls++;return {status:'APPLIED',authorityId:'cfg-authority'}}}});a.beginProposal('runtime.maxItems','14');const p=a.validate('runtime.maxItems');assert(p.state==='VALIDATED'&&p.application==='NOT_APPLIED'&&calls===0)},tests);
  run('S19.configuration.version-conflict-is-invalid-not-authority',()=>{const a=new ConfigurationDomainAdapter({observations:[obs()]});a.beginProposal('runtime.maxItems','14');(a       ).observations[0].presentVersion='v8';const p=a.validate('runtime.maxItems');assert(p.state==='INVALID'&&p.validation.reason==='VERSION_CONFLICT'&&p.application==='NOT_APPLIED')},tests);
  run('S19.configuration.reset-discards-only-proposal',()=>{const a=new ConfigurationDomainAdapter({observations:[obs()]});a.beginProposal('runtime.maxItems','14');const r=a.reset('runtime.maxItems');assert(r.ok&&r.factoryReset===false&&r.liveConfigMutation===false&&r.presentVersion==='v7'&&!a.proposal('runtime.maxItems'))},tests);
  run('S19.configuration.sensitive-key-is-rejected-before-proposal',()=>{const a=new ConfigurationDomainAdapter({observations:[obs({key:'provider.apiKey',redactedValue:'[REDACTED]'})]});let failed=false;try{a.beginProposal('provider.apiKey','do-not-store')}catch(error){failed=String((error       ).message).includes('SENSITIVE_CONFIG_KEY_EXCLUDED')}assert(failed&&!a.proposal('provider.apiKey')&&JSON.stringify(a.diagnosticProjection()).includes('do-not-store')===false)},tests);
  run('S19.configuration.diff-never-reveals-observed-plaintext',()=>{const a=new ConfigurationDomainAdapter({observations:[obs()]});a.beginProposal('runtime.maxItems','14');const r=a.diff('runtime.maxItems');assert(r.ok&&r.observedRedacted==='***12'&&r.redactionApplied===true&&r.containsObservedPlaintext===false)},tests);
  run('S19.configuration.requestApply-without-authority-stays-pending-not-applied',()=>{const a=new ConfigurationDomainAdapter({observations:[obs()]});a.beginProposal('runtime.maxItems','14');a.validate('runtime.maxItems');const r=a.requestApply('runtime.maxItems');assert(!r.ok&&r.code==='AUTHORITY_PENDING'&&r.authorityBound===true&&r.proposal.state==='AUTHORITY_PENDING'&&r.proposal.application==='NOT_APPLIED')},tests);
  run('S19.configuration.requestApply-calls-only-explicit-authority',()=>{let calls=0;const a=new ConfigurationDomainAdapter({observations:[obs()],authority:{id:'cfg-authority',requestApply:proposal=>{calls++;assert(proposal.state==='AUTHORITY_PENDING'&&proposal.application==='APPLY_REQUESTED');return {status:'APPLY_REQUESTED',authorityId:'cfg-authority'}}}});a.beginProposal('runtime.maxItems','14');a.validate('runtime.maxItems');const r=a.requestApply('runtime.maxItems');assert(r.ok&&calls===1&&r.authorityBound===true&&r.proposal.application==='APPLY_REQUESTED')},tests);
  run('S19.configuration.global-settings-remains-separate-owner',()=>{const c=createConfigurationSurfaceComposition();assert(c.slots.CENTER==='OperationalConfigInspectionWorkbench'&&c.settingsBoundary.globalSettingsOwner==='SettingsCenterOwner'&&c.settingsBoundary.operationalConfigurationOwner==='ConfigurationDomainAdapter'&&c.settingsBoundary.duplicateSettingsEngine===false&&c.settingsBoundary.settingsCanDispatchOperationalConfigApply===false)},tests);
  run('S19.configuration.diagnostics-withhold-proposal-values',()=>{const a=new ConfigurationDomainAdapter({observations:[obs()]});a.beginProposal('runtime.maxItems','sensitive-by-context-value');const serialized=JSON.stringify(a.diagnosticProjection());assert(serialized.includes('sensitive-by-context-value')===false&&serialized.includes('PROPOSAL_VALUE_WITHHELD_FROM_DIAGNOSTICS'))},tests);
  return tests;
}
if(import.meta.url===new URL(process.argv[1],'file:').href){const tests=runS19Tests(),report={lane:'S19_W05_RELEASES_CONFIGURATION',pass:tests.filter(x=>x.status==='PASS').length,fail:tests.filter(x=>x.status==='FAIL').length,tests};console.log(JSON.stringify(report,null,2));if(report.fail)process.exitCode=1;}
